from src.app import handle

class QuoteTest(unittest.TestCase):
    def test_quote(self):
        self.assertEqual(handle('/quote', {'symbol': 'ABC'}, {'MARKET_API_URL': 'https://market.invalid'}), (200, {'symbol': 'ABC', 'price': 12.5}))
    def test_invalid(self):
        self.assertEqual(handle('/quote', {'symbol': ' '}, {'MARKET_API_URL': 'https://market.invalid'})[0], 422)
    def test_missing_price(self):
        self.assertIsNone(handle('/quote', {'symbol': 'ABC', 'price': None}, {'MARKET_API_URL': 'https://market.invalid'})[1]['price'])

